	ListInternalWalletAddresses(context.Context, *ListInternalWalletAddressesReq) (*ListInternalWalletAddressesResp, error)
	AddInternalWalletAddress(context.Context, *AddInternalWalletAddressReq) (*AddInternalWalletAddressResp, error)
	UpdateInternalWalletAddress(context.Context, *UpdateInternalWalletAddressReq) (*UpdateInternalWalletAddressResp, error)
	DeleteInternalWalletAddress(context.Context, *DeleteInternalWalletAddressReq) (*DeleteInternalWalletAddressResp, error)
	LookupInternalUser(context.Context, *LookupInternalUserReq) (*LookupInternalUserResp, error)
