	ListPriceUnitOptions(context.Context, *ListPriceUnitOptionsReq) (*ListPriceUnitOptionsResp, error)
	SetPreferences(context.Context, *SetPreferencesReq) (*SetPreferencesResp, error)
	// 获取客户端配置
	GetClientConfig(context.Context, *GetClientConfigReq) (*GetClientConfigResp, error)
