	SwapGetQuote(context.Context, *BusinessSwapGetQuoteRequest) (*BusinessSwapGetQuoteResponse, error)
	SwapExecuteSwap(context.Context, *BusinessSwapExecuteSwapRequest) (*BusinessSwapExecuteSwapResponse, error)
	SwapGetApprovalTransaction(context.Context, *BusinessSwapGetApprovalTransactionRequest) (*BusinessSwapGetApprovalTransactionResponse, error)
	SwapResetApproval(context.Context, *BusinessSwapResetApprovalRequest) (*BusinessSwapResetApprovalResponse, error)
	SwapGetSwapStatus(context.Context, *BusinessSwapGetSwapStatusRequest) (*BusinessSwapGetSwapStatusResponse, error)
	SwapGetSwapDetail(context.Context, *BusinessSwapGetSwapDetailRequest) (*BusinessSwapGetSwapDetailResponse, error)
	SwapGetSwapHistory(context.Context, *BusinessSwapGetSwapHistoryRequest) (*BusinessSwapGetSwapHistoryResponse, error)
