	SwapGetSupportedChains(context.Context, *BusinessSwapGetSupportedChainsRequest) (*BusinessSwapGetSupportedChainsResponse, error)
	SwapGetExternalSwapStatus(context.Context, *BusinessSwapGetExternalSwapStatusRequest) (*BusinessSwapGetExternalSwapStatusResponse, error)
