	GetWeb3UserByDeviceId(context.Context, *GetWeb3UserByDeviceIdReq) (*GetWeb3UserByDeviceIdResp, error)
	// 获取 Web3 用户资产概览
	GetWeb3AssetOverview(context.Context, *GetWeb3AssetOverviewReq) (*GetWeb3AssetOverviewResp, error)
	// 获取 Web3 用户交易记录列表
	ListWeb3Transactions(context.Context, *ListWeb3TransactionsReq) (*ListWeb3TransactionsResp, error)
	// 获取 Web3 交易详情
	GetWeb3TransactionDetail(context.Context, *GetWeb3TransactionDetailReq) (*GetWeb3TransactionDetailResp, error)
