	ListWeb3SupportedAssets(context.Context, *ListWeb3SupportedAssetsReq) (*ListWeb3SupportedAssetsResp, error)
	// 获取 Web3 用户地址的 Nonce（用于构建 EVM 交易）
	GetWeb3Nonce(context.Context, *GetWeb3NonceReq) (*GetWeb3NonceResp, error)
